ALTER TABLE `events` ADD COLUMN `eventNumber` INT AFTER `id`;
ALTER TABLE `events` ADD COLUMN `theme` VARCHAR(255) AFTER `location`;
ALTER TABLE `events` ADD COLUMN `status` ENUM('recruiting', 'recruiting_complete', 'ongoing', 'completed') DEFAULT 'recruiting' NOT NULL AFTER `capacity`;
ALTER TABLE `events` ADD COLUMN `googleSheetTabId` VARCHAR(255) AFTER `status`;
ALTER TABLE `events` MODIFY COLUMN `description` TEXT;
ALTER TABLE `events` MODIFY COLUMN `location` VARCHAR(255) NOT NULL;
ALTER TABLE `events` MODIFY COLUMN `capacity` INT DEFAULT 0;

ALTER TABLE `memberProfiles` ADD COLUMN `phone` VARCHAR(20) UNIQUE AFTER `applicationId`;
ALTER TABLE `memberProfiles` ADD COLUMN `name` VARCHAR(255) AFTER `phone`;

CREATE TABLE IF NOT EXISTS `eventRegistrations` (
  `id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `eventId` INT NOT NULL,
  `memberId` INT,
  `name` VARCHAR(255) NOT NULL,
  `company` VARCHAR(255),
  `phone` VARCHAR(20) NOT NULL,
  `email` VARCHAR(320),
  `additionalInfo` TEXT,
  `registrationType` ENUM('existing_member', 'new_participant') NOT NULL,
  `createdAt` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  FOREIGN KEY (`eventId`) REFERENCES `events`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`memberId`) REFERENCES `memberProfiles`(`id`) ON DELETE SET NULL,
  UNIQUE KEY `unique_registration` (`eventId`, `phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

